#[tokio::test]
async fn status_cancels_without_waiting_for_a_missing_host_reply() {
    let (rt, host) = setup("sound-effects").await;
    let context = InvocationContext::default();
    let cancellation = context.cancellation.clone();
    let mut invocation = std::pin::pin!(rt.registry().invoke("project.classic.automation.status", context, input(&rt)));
    assert!(invocation.as_mut().poll(&mut Context::from_waker(Waker::noop())).is_pending());
    assert_eq!(host.pending().unwrap().len(), 1);
    cancellation.cancel();
    assert!(invocation.await.is_err());
    assert!(host.pending().unwrap().is_empty());
}
